import { LineItem } from '../types';

export interface WhatsAppCartParsedResult {
  items: LineItem[];
  customerName?: string;
  customerPhone?: string;
  customerAddress?: string;
  orderNumber?: string;
  notes?: string;
  estimatedTotal?: number;
  rawText: string;
}

/**
 * Parses messages generated by WhatsApp Business Cart or customer order summaries.
 * Handles formats like:
 * - *Novo pedido recebido*
 * - • 1x Top coat incolor (R$ 15,00)
 * - • 2x Base bomba (R$ 37,00)
 * - Total estimado: R$ 64,00
 * - Cliente / Telefone / Endereço / Observações
 */
export function parseWhatsAppCartMessage(rawText: string): WhatsAppCartParsedResult {
  const result: WhatsAppCartParsedResult = {
    items: [],
    rawText,
  };

  if (!rawText || !rawText.trim()) {
    return result;
  }

  const lines = rawText.split(/\r?\n/).map((l) => l.trim());

  // 1. Extract Customer Info (Name, Phone, Address)
  for (const line of lines) {
    // Customer Name
    const nameMatch = line.match(/(?:cliente|nome|comprador|destinat[aá]rio)[\s:*-]+([^\n\r]+)/i);
    if (nameMatch && nameMatch[1] && !result.customerName) {
      const cleanName = nameMatch[1].replace(/[*_~]/g, '').trim();
      if (cleanName.length > 1 && !/(?:pedido|carrinho|total)/i.test(cleanName)) {
        result.customerName = cleanName;
      }
    }

    // Phone / WhatsApp
    const phoneMatch = line.match(/(?:telefone|whatsapp|celular|fone|tel)[\s:*-]+([0-9()+\-\s]{8,20})/i);
    if (phoneMatch && phoneMatch[1] && !result.customerPhone) {
      result.customerPhone = phoneMatch[1].trim();
    }

    // Address / Delivery
    const addrMatch = line.match(/(?:endere[çc]o|entrega|rua|av(?:enida)?)[\s:*-]+([^\n\r]+)/i);
    if (addrMatch && addrMatch[1] && !result.customerAddress) {
      result.customerAddress = addrMatch[1].replace(/[*_~]/g, '').trim();
    }

    // Order Number
    const orderNumMatch = line.match(/(?:pedido|order|n[ºo°]|fatura)[\s:#*-]*([a-z0-9\-_]+)/i);
    if (orderNumMatch && orderNumMatch[1] && !result.orderNumber) {
      const rawNum = orderNumMatch[1].replace(/[*_~]/g, '').trim();
      if (rawNum.length >= 3 && !/(?:recebido|whatsapp|novo)/i.test(rawNum)) {
        result.orderNumber = rawNum.toUpperCase();
      }
    }

    // Total estimado
    const totalMatch = line.match(/(?:total(?:\s+estimado)?|valor\s+total)[\s:*-]*(?:R\$|\$|€)?\s*([0-9]+[.,][0-9]{2})/i);
    if (totalMatch && totalMatch[1]) {
      result.estimatedTotal = parseFloat(totalMatch[1].replace('.', '').replace(',', '.'));
    }
  }

  // 2. Parse Items
  // Look for lines that look like cart items:
  // Examples:
  // • 1x Top coat incolor (R$ 15,00)
  // • 2 x Base bomba - R$ 18,50
  // 1x Removedor de esmalte R$ 12,00
  // #01 Top coat incolor 1 un R$ 15,00
  const extractedItems: LineItem[] = [];

  for (let i = 0; i < lines.length; i++) {
    let line = lines[i];
    if (!line) continue;

    // Skip general header lines and footer lines
    if (
      /^\*?(?:novo\s+pedido|itens\s+do\s+pedido|carrinho|pedido\s+recebido|resumo\s+do\s+pedido)\*?$/i.test(
        line.replace(/[*_~]/g, '').trim()
      )
    ) {
      continue;
    }
    if (/(?:total\s+estimado|forma\s+de\s+pagamento|chave\s+pix|obrigado|chave\s+de\s+acesso)/i.test(line)) {
      continue;
    }
    if (/(?:cliente|telefone|whatsapp|endere[çc]o|entrega)[\s:*-]+/i.test(line)) {
      continue;
    }

    // Clean bullets and markdown asterisks
    let workingLine = line
      .replace(/^[•\-\*–—\s>]+/, '')
      .replace(/[*_~]/g, '')
      .trim();

    if (workingLine.length < 3) continue;

    // Detect Code/SKU if present (#01, COD: 101, 1.)
    let code = `WA-${101 + extractedItems.length}`;
    const hashMatch = workingLine.match(/^#([0-9]{1,6})\b[:\s-]*/);
    if (hashMatch) {
      code = `#${hashMatch[1]}`;
      workingLine = workingLine.slice(hashMatch[0].length).trim();
    } else {
      const codMatch = workingLine.match(/^(?:c[óo]d(?:igo)?|sku|ref(?:er[êe]ncia)?)[\s.:#-]*([a-z0-9\-_]+)[:\s-]*/i);
      if (codMatch) {
        code = codMatch[1].toUpperCase();
        workingLine = workingLine.slice(codMatch[0].length).trim();
      } else {
        const numMatch = workingLine.match(/^(\d{1,3})[\.\)\-]\s+/);
        if (numMatch) {
          code = numMatch[1];
          workingLine = workingLine.slice(numMatch[0].length).trim();
        }
      }
    }

    // Extract quantity (e.g. "1x", "2 x", "3 un", "qtd: 2")
    let quantity = 1;
    const qtyRegexes = [
      /^([0-9]{1,3})\s*(?:x|un|und|cx|pc|pçs)\b[:\s-]*/i,
      /\b([0-9]{1,3})\s*(?:x|un|und|cx|pc|pçs)\b/i,
      /(?:qtd|quant|quantidade)[\s:]*([0-9]{1,3})\b/i,
    ];

    for (const rx of qtyRegexes) {
      const qMatch = workingLine.match(rx);
      if (qMatch && qMatch[1]) {
        const val = parseInt(qMatch[1], 10);
        if (val > 0 && val < 500) {
          quantity = val;
          workingLine = workingLine.replace(qMatch[0], ' ').trim();
          break;
        }
      }
    }

    // Extract price (e.g. "(R$ 15,00)", "R$ 18,50", "15.00")
    let unitPrice = 0;
    const priceMatch = workingLine.match(/(?:\(?\s*(?:R\$|\$|€)?\s*([0-9]+[.,][0-9]{2})\s*\)?)/i);
    if (priceMatch && priceMatch[1]) {
      const rawPriceStr = priceMatch[1];
      unitPrice = parseFloat(rawPriceStr.replace('.', '').replace(',', '.'));
      workingLine = workingLine.replace(priceMatch[0], ' ').trim();
    }

    // Clean remaining description
    let description = workingLine
      .replace(/^[–—\-:;,•()\s]+/, '')
      .replace(/[–—\-:;,()\s]+$/, '')
      .replace(/\s{2,}/g, ' ')
      .trim();

    // If description is empty or too short, skip
    if (!description || description.length < 2) continue;

    // Check if next line contains quantity/price if not found in current line
    if (unitPrice === 0 && i + 1 < lines.length) {
      const nextLine = lines[i + 1];
      const nextPriceMatch = nextLine.match(/(?:R\$|\$|€)?\s*([0-9]+[.,][0-9]{2})/i);
      if (nextPriceMatch) {
        unitPrice = parseFloat(nextPriceMatch[1].replace('.', '').replace(',', '.'));
        i++; // skip next line
      }
    }

    extractedItems.push({
      id: `wa-item-${Date.now()}-${extractedItems.length}`,
      code,
      description,
      quantity,
      unitPrice,
      total: quantity * unitPrice,
    });
  }

  result.items = extractedItems;
  return result;
}

/**
 * Ready-to-use sample WhatsApp cart message for testing.
 */
export const SAMPLE_WHATSAPP_CART_MESSAGE = `*Novo pedido recebido*

• 1x Top coat incolor (R$ 15,00)
• 2x Base bomba (R$ 37,00)
• 1x Removedor a base de acetona (R$ 12,00)

Total estimado: R$ 64,00

Cliente: Mariana Silva
Telefone: (11) 98765-4321
Endereço: Av. Paulista, 1500 - Bela Vista, São Paulo - SP
Observação: Entregar no período da tarde`;
